import { CampusAPI } from './api.js';
import { people, interests, goals, groups, titles } from './data.js';
import { esc, money, date, age, remaining, safeImage, safePaymentUrl, encodeMeeting, decodeMeeting } from './utils.js';

const $ = selector => document.querySelector(selector);
const storage={get:(key)=>{try{return sessionStorage.getItem(key);}catch{return null;}},set:(key,value)=>{try{sessionStorage.setItem(key,value);}catch{}},remove:key=>{try{sessionStorage.removeItem(key);}catch{}}};
const state={demo:storage.get('campus-demo')==='true',me:null,feed:[],matches:[],events:[],tickets:[],reports:[],messages:[],meetings:[],subscription:null,pass:null,reportStatus:'OPEN',history:[],partners:[],editEvent:null,blocks:[],daily:[],selected:null,event:null,match:null,report:null,ticket:null,payment:null,paymentKey:null,meeting:null,photo:0,stepEmail:'',birth:'',consent:false,university:'УрФУ',institute:'ИРИТ-РтФ',draft:null,filter:{goal:'',university:''},category:'Все',likes:[],tab:'mutual',loading:false,error:'',search:'',stats:null,reportResult:null,localPhotos:[]};
const api=new CampusAPI({demo:state.demo,token:storage.get('campus-token') || '',onUnauthorized:()=>{storage.remove('campus-token');api.token='';state.me=null;go('email');}});
let route=location.hash.slice(1)||'welcome',sequence=0,toastTimer,pollTimer;
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',calendar:'M4 5h16v16H4z M7 2v6 M17 2v6 M4 10h16',chat:'M21 11a9 9 0 0 1-9 9H4l-2 2v-10a9 9 0 0 1 19-1Z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3Z',arrow:'M4 12h16 M14 6l6 6-6 6',back:'M20 12H4 M10 6l-6 6 6 6',close:'M5 5l14 14 M19 5 5 19',check:'M4 12l5 5L20 6',filter:'M3 6h18 M3 12h18 M3 18h18 M7 3v6 M16 9v6 M10 15v6',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6Z M7 12l3 3 7-7',mail:'M2 5h20v14H2Z M2 5l10 8L22 5',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 3',ticket:'M3 4h18v5a3 3 0 0 0 0 6v5H3v-5a3 3 0 0 0 0-6Z M15 4v16',settings:'M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',plus:'M12 4v16 M4 12h16',send:'m3 3 19 9-19 9 4-9Z M7 12h15',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',edit:'m4 16 12-12 4 4L8 20H4Z M14 6l4 4',card:'M2 5h20v15H2z M2 10h20 M6 16h4',download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5',book:'M12 5C8 2 3 4 3 4v16s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Z M12 5v16',logout:'M10 3H3v18h7 M8 12h14 M17 7l5 5-5 5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.heart}"/></svg>`;
const button=(label,action,style='primary',ico='arrow',extra='')=>`<button class="btn ${style}" type="button" data-action="${action}" ${extra}>${label}${ico?icon(ico):''}</button>`;
const next=(label='Продолжить')=>`<button class="btn primary" type="submit">${label}${icon('arrow')}</button>`;
const heading=(title,copy='')=>`<div class="section-heading"><h1>${title}</h1><span class="spark" aria-hidden="true">╱</span></div>${copy?`<p class="intro">${copy}</p>`:''}`;
const note=(text,ico='shield')=>`<div class="note">${icon(ico)}<div>${text}</div></div>`;
const tag=(text)=>`<span class="tag">${esc(text)}</span>`;
const input=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const photo=(person)=>safeImage(person?.photos?.[state.photo % (person?.photos?.length || 1)]?.storageKey) || '';
const avatar=(p,cls='')=>photo(p)?`<img class="avatar ${cls}" src="${esc(photo(p))}" alt="${esc(p?.name || 'Фото профиля')}">`:`<span class="avatar fallback ${cls}">${esc(p?.name?.[0] || '?')}</span>`;
const eventImage=e=>safeImage(e?.posterUrl || e?.image) || '/assets/concert.jpg';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function go(to){if(['chat','meeting','meeting-card'].includes(to)&&state.match)storage.set('campus-match',state.match.id);if(['ticket','reservation'].includes(to)&&state.ticket)storage.set('campus-ticket',state.ticket.eventId);if(location.hash==='#'+to)load();else location.hash=to;}
function rememberCheckout(){if(!state.demo&&state.me&&state.paymentKey)storage.set('campus-checkout',JSON.stringify({userId:state.me.id,paymentId:state.payment?.id,kind:state.payment?.kind || 'TICKET',eventId:state.ticket?.eventId,key:state.payment?.idempotencyKey || state.paymentKey,created:!!state.payment}));}
function choosePerson(id){state.selected=state.feed.find(p=>p.userId===id)||people.find(p=>p.userId===id)||state.selected;state.photo=0;}
function selectedEvent(){return state.event || state.events[0];}
function selectedPerson(){return state.selected || state.feed[0] || (state.demo?people[0]:null);}
function draft(){return state.draft ||= structuredClone(state.me?.profile || {name:'',university:state.university,institute:state.institute,goal:'DATING',about:'',interests:[],hideFromInstitute:false,photos:[]});}
function nav(){const active=['feed','person','filters','empty','match'].includes(route)?'feed':['matches'].includes(route)?'matches':['events','event','reservation','tickets','ticket','sold-out'].includes(route)?'events':['chats','chat','meeting','meeting-card'].includes(route)?'chats':'profile';return `<nav class="bottom-nav" aria-label="Основная навигация">${[['feed','home','Лента'],['matches','heart','Симпатии'],['events','calendar','События'],['chats','chat','Чаты'],['profile','user','Профиль']].map(([r,i,label])=>`<button data-go="${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;}
function shell(content){const auth=['welcome','birth','university','email','code','verified'].includes(route);const showNav=!auth && !['filters','report','report-sent','checkout','payment-pending','payment-success','payment-failed','expired','meeting','photos','interests','edit-profile'].includes(route);return `<div class="desktop-shell"><aside class="brand-panel"><a class="wordmark" href="#welcome">CAMPUS<span>®</span></a><div class="brand-statement">ТВОЙ<br>ЧЕЛОВЕК<br><em>ГДЕ-ТО<br>МЕЖДУ<br>ПАРАМИ.</em></div><div class="brand-bottom"><span class="hand-heart">♡</span><p>Знакомства, дружба<br>и немного спонтанности.</p><span class="eyebrow">ЕКАТЕРИНБУРГ · 18+</span></div></aside><main class="phone ${auth?'auth':''}"><div class="mode-bar"><span class="dot"></span>${state.demo?'Деморежим · данные для знакомства':'Студенческое комьюнити · 18+'}${state.demo?'<button data-action="exit-demo">Выйти</button>':''}</div><header><button class="icon-btn back" data-action="back" aria-label="Назад">${icon('back')}</button><a class="wordmark" href="#${state.me?'feed':'welcome'}">CAMPUS</a><button class="header-location" data-go="${state.me?'filters':'university'}">${icon('pin')}${esc(state.me?.profile?.university || state.university)}</button><button class="icon-btn" data-go="${state.me?'settings':'welcome'}" aria-label="Настройки">${icon('filter')}</button></header><div id="screen" class="screen ${route}">${state.loading?'<div class="loading" role="status"><span class="spinner"></span>Собираем твоё пространство…</div>':content}</div>${showNav?nav():''}</main><aside class="context-panel"><span class="eyebrow">СВОИ ЛЮДИ РЯДОМ</span><h2>Начнётся<br>с «привет».</h2><p>Общие интересы.<br>Один кампус.<br>Много поводов встретиться.</p><div class="context-art">✳<span>♡</span></div>${note('Только студенты.<br>Только с подтверждённой<br>университетской почтой.','shield')}<a class="text-link" href="#safety">Правила сообщества ${icon('arrow')}</a>${state.demo?`<details class="screen-map"><summary>Все 42 экрана ${icon('book')}</summary>${groups.map(([name,routes])=>`<fieldset><legend>${name}</legend>${routes.map(r=>`<button data-go="${r}" class="${route===r?'current':''}">${titles[r]}</button>`).join('')}</fieldset>`).join('')}<a href="/assets/references/01-onboarding.png" target="_blank" rel="noopener">Исходные макеты ↗</a></details>`:button('Посмотреть демо','start-demo','outline','arrow')}</aside></div>`;}
function render(){document.documentElement.dataset.theme=state.me?.profile?.theme || 'light';document.title=`${titles[route] || 'CAMPUS'} · CAMPUS`;$('#app').innerHTML=shell(view());if(state.error){const box=document.createElement('div');box.className='error';box.setAttribute('role','alert');box.textContent=state.error;$('#screen').prepend(box);}if(state.demo && !$('.mobile-explorer')){$('.phone').insertAdjacentHTML('beforeend',`<details class="mobile-explorer"><summary>Демо: перейти к экрану</summary><select aria-label="Экран демо" id="screen-select"><option value="">Выбрать экран</option>${groups.map(([name,routes])=>`<optgroup label="${name}">${routes.map(r=>`<option value="${r}" ${r===route?'selected':''}>${titles[r]}</option>`).join('')}</optgroup>`).join('')}</select></details>`);}updateTimers();}
function view(){
 const p=selectedPerson(),e=selectedEvent(),d=draft();
 switch(route){
 case 'welcome':return `<span class="eyebrow">ТВОЙ КАМПУС. ТВОИ ЛЮДИ.</span>${heading('Твой человек<br>где-то между<br>парами','Знакомства для студентов.<br>Учёба, тусовки, события<br>и отношения на кампусе.')}<div class="welcome-collage"><img src="/assets/anya.jpg" alt="Улыбающаяся студентка на кампусе"><img src="/assets/mark.jpg" alt="Студент с наушниками"><span class="collage-label">Увидимся после пар ↗</span><span class="doodle">♡</span></div><div class="push-bottom">${button('Начать знакомиться','onboarding')}${button('Посмотреть демо','start-demo','ghost','') }<div class="small centered">Для студентов от 18 лет</div></div>`;
 case 'birth':return `${heading('Когда ты<br>родился(-ась)?','Знакомства для студентов от 18 лет.')}<form data-form="birth">${input('birthDate','Дата рождения',state.birth,'date','required max="'+new Date().toISOString().slice(0,10)+'"')}${note('Нам важно, чтобы здесь всем было комфортно и безопасно.','user')}<label class="check-row"><input type="checkbox" name="consent" required ${state.consent?'checked':''}><span>Соглашаюсь с <a href="#privacy-policy">политикой конфиденциальности</a> и обработкой персональных данных</span></label>${next()}</form>`;
 case 'university':return `${heading('Какой у тебя<br>университет?','Выбери свой вуз и институт,<br>чтобы находить своих.')}<form data-form="university"><div class="radio-stack">${[['УрФУ','Уральский федеральный университет'],['УГМУ','Уральский государственный медицинский университет'],['УрГЭУ','Уральский государственный экономический университет']].map(([v,t])=>`<label class="choice"><input type="radio" name="university" value="${v}" ${state.university===v?'checked':''}><span><strong>${v}</strong><small>${t}</small></span></label>`).join('')}</div>${input('institute','Факультет / институт',state.institute,'text','required minlength="2" maxlength="80"')}${next()}</form>`;
 case 'email':return `${heading('Подтверди<br>статус студента','Введи свою университетскую почту, чтобы подтвердить, что ты действующий студент.')}<form data-form="email">${input('email','Почта вуза',state.stepEmail,'email','required placeholder="anna@urfu.me" autocomplete="email"')}${note('<strong>Зачем это нужно?</strong><br>Так в CAMPUS только реальные студенты. Твоя почта не появится в анкете.','mail')}${next('Получить код')}</form>`;
 case 'code':return `${heading('Введи код<br>из письма',`Мы отправили шестизначный код на почту <strong>${esc(state.stepEmail)}</strong>.`)}<form data-form="code">${input('code','Код подтверждения','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="− − − − − −" class="code-input"')}${state.demo?note('В деморежиме введи <strong>123456</strong>.','mail'):''}<button class="text-link resend" data-action="resend" type="button" ${Date.now()<Number(storage.get('campus-resend'))?'disabled':''}>Отправить ещё раз <span data-resend></span></button><button class="text-link" type="button" data-go="email">Изменить почту</button>${next('Подтвердить')}</form>`;
 case 'verified':return `<div class="success-symbol">${icon('check')}</div>${heading('Теперь ты<br>среди своих')}${note('<strong>Статус студента подтверждён</strong>','shield')}<p class="intro">Тебя ждут знакомства, события на кампусе и новые люди из твоего университета.</p><div class="push-bottom">${button('Создать анкету','create-profile')}</div>`;
 case 'edit-profile':return `${heading('Расскажи о себе','Начнём с самого интересного — с тебя.')}<form data-form="profile">${input('name','Имя',d.name,'text','required maxlength="40" autocomplete="given-name"')}${input('university','Университет',d.university,'text','required minlength="2" maxlength="80"')}${input('institute','Факультет и курс',d.institute,'text','required minlength="2" maxlength="80"')}<fieldset class="goal-options"><legend>Цель на CAMPUS</legend>${Object.entries(goals).map(([value,label])=>`<label class="goal"><input type="radio" name="goal" value="${value}" ${d.goal===value?'checked':''}>${label}</label>`).join('')}</fieldset><label class="field">О себе<textarea name="about" maxlength="500" rows="4" placeholder="Что делает тебя тобой?">${esc(d.about)}</textarea></label>${next('Дальше')}</form>`;
 case 'interests':return `${heading('Что вас сблизит?','Выбери от 3 до 10 интересов.')}<div class="chips interest-picker">${interests.map(i=>`<button data-interest="${i}" class="chip ${d.interests.includes(i)?'selected':''}" aria-pressed="${d.interests.includes(i)}">${esc(i)}${d.interests.includes(i)?icon('check'):''}</button>`).join('')}</div><div class="push-bottom"><p class="small">Выбрано ${d.interests.length} из 10</p>${button('Сохранить анкету','save-profile','primary','check')}</div>`;
 case 'photos':return `${heading('Добавь фото','Покажи, какой ты в жизни. От 1 до 6 фото.')}<div class="photo-grid">${(state.me?.profile?.photos || []).map((ph,i)=>`<div class="photo-slot">${safeImage(ph.storageKey)?`<img src="${esc(safeImage(ph.storageKey))}" alt="Фото ${i+1}">`:`<span class="photo-key">${esc(ph.storageKey)}</span>`}<button class="remove-photo" data-remove-photo="${esc(ph.id)}" aria-label="Удалить фото ${i+1}">×</button>${i===0?'<span class="cover-label">Обложка</span>':!state.demo?`<button class="cover-label" data-cover-photo="${esc(ph.id)}" aria-label="Сделать фото ${i+1} обложкой">☆ Обложка</button>`:''}</div>`).join('')}${Array.from({length:Math.max(0,6-(state.me?.profile?.photos?.length || 0))},()=>'<div class="photo-slot empty-slot">+<small>Добавь своё фото</small></div>').join('')}</div><form data-form="photo">${state.demo?input('storageKey','Ссылка на фото (HTTP/HTTPS)','','text','required maxlength="300" placeholder="https://…"'):input('file','Выбери фото с устройства','','file','required accept="image/jpeg,image/png,image/webp"')}${next('Добавить фото')}</form>${!state.demo?note('JPEG, PNG или WebP, до 5 МБ. Нажми на звёздочку, чтобы сделать фото обложкой.','book'):''}${button('Готово','finish-photos','outline','check')}`;
 case 'profile':{const me=state.me?.profile;return me?`${me.photos?.length&&safeImage(me.photos[0].storageKey)?`<img class="profile-cover" src="${esc(safeImage(me.photos[0].storageKey))}" alt="Твоё фото">`:'<div class="profile-placeholder">'+icon('user')+'</div>'}<div class="profile-title"><h1>${esc(me.name)}${state.me.birthDate?', '+age(state.me.birthDate):''}<span class="verified-badge">✓</span></h1><button class="icon-btn" data-action="edit-profile" aria-label="Редактировать">${icon('edit')}</button></div><p>${esc(me.institute)} · ${esc(me.university)}</p><blockquote>${esc(me.about || 'Здесь будет твоя история')}</blockquote><div class="chips">${me.interests.map(tag).join('')}</div><div class="two-buttons">${button('Фотографии','open-photos','outline','user')}${button('Настройки','settings','outline','settings')}</div>${button('CAMPUS Premium','premium','premium-btn','heart')}${state.demo||['MODERATOR','ADMIN'].includes(state.me.role)?button('Раздел команды','team','ghost','shield'):''}`:`${heading('Твоя история<br>начинается здесь')}${button('Заполнить анкету','create-profile')}`;}
 case 'settings':return `${heading('Настройки')}<div class="list">${listButton('Внешний вид и уведомления','Тема и уведомления CAMPUS','preferences','settings')}${listButton('Заблокированные','Управление блокировками','blocks','shield')}${listButton('Приватность','Кто видит твою анкету','privacy','shield')}${listButton('Анкета','Имя, интересы и цель знакомства','edit-profile','user')}${listButton('Фотографии','Управление фотографиями','photos','edit')}${listButton('История платежей','Билеты и Premium','history','card')}${listButton('Мои билеты','Все события в одном месте','tickets','ticket')}${listButton('Правила сообщества','Для твоего комфорта и безопасности','safety','shield')}${listButton('Аккаунт',esc(state.me?.universityEmail),'account','mail')}</div>${button('Выйти из аккаунта','logout','outline','logout')}`;
 case 'privacy':return `${heading('Приватность')}<form data-form="privacy"><label class="switch-card"><span><strong>Скрыть от своего института</strong><small>Твой профиль не будет показываться студентам твоего института.</small></span><input type="checkbox" name="hide" role="switch" ${state.me?.profile?.hideFromInstitute?'checked':''}></label><label class="switch-card"><span><strong>Показывать анкету в ленте</strong><small>Управляй видимостью своей анкеты.</small></span><input type="checkbox" name="visible" role="switch" ${state.me?.profile?.isVisible!==false?'checked':''}></label>${note('Ты по-прежнему можешь общаться с теми, с кем уже совпал.','shield')}${next('Сохранить')}</form>${button('Удалить аккаунт','delete-confirm','danger','close')}`;
 case 'delete-confirm':return `${heading('Удалить аккаунт?','Анкета, фотографии, переписки, билеты и остальные данные будут удалены. Это действие нельзя отменить.')}<form data-form="delete"><label class="check-row"><input type="checkbox" name="confirm" required><span>Я понимаю, что мои данные будут удалены</span></label>${next('Удалить навсегда')}</form>${button('Оставить аккаунт','profile','outline','back')}`;
 case 'feed':{const first=state.feed[0];return `${heading('Знакомься<br>со студентами<br>твоего университета')}<div class="feed-toolbar"><span>${state.feed.length} анкет для тебя</span><button class="text-link" data-go="filters">${icon('filter')} Фильтры</button></div>${first?personCard(first)+`<div class="swipe-actions"><button data-action="pass" aria-label="Пропустить анкету" class="pass">${icon('close')}</button><button data-action="like" aria-label="Поставить симпатию" class="like">${icon('heart')}</button></div>`:emptyView()}`;}
 case 'person':return p?`${photo(p)?`<div class="person-photo"><img src="${esc(photo(p))}" alt="${esc(p.name)}"><span class="photo-count">${state.photo+1}/${p.photos.length}</span>${p.photos.length>1?`<button class="photo-prev" data-action="prev-photo" aria-label="Предыдущее фото">‹</button><button class="photo-next" data-action="next-photo" aria-label="Следующее фото">›</button>`:''}</div>`:''}${heading(`${esc(p.name)}${p.age?', '+p.age:''} <span class="verified-badge">✓</span>`)}<p>${icon('book')} ${esc(p.institute)}</p><p>${icon('pin')} ${esc(p.university)}, Екатеринбург</p><p class="about">${esc(p.about)}</p><h3>Общие интересы</h3><div class="chips">${(p.interests || []).map(tag).join('')}</div>${button('Поставить симпатию','like-person','primary','heart')}${button('Пожаловаться','report','ghost','shield')}${!state.demo?button('Заблокировать','block-person','ghost','close'):''}`:emptyView();
 case 'filters':return `${heading('Фильтры','Найдём тех, с кем вы на одной волне.')}<form data-form="filters">${input('university','Университет',state.filter.university,'text','placeholder="Любой университет"')}${!state.demo?`<div class="two-fields">${input('minAge','Возраст от',state.filter.minAge || '18','number','min="18" max="100"')}${input('maxAge','Возраст до',state.filter.maxAge || '100','number','min="18" max="100"')}</div>`:''}<label class="field">Цель знакомства<select name="goal"><option value="">Все цели</option>${Object.entries(goals).map(([v,t])=>`<option value="${v}" ${state.filter.goal===v?'selected':''}>${t}</option>`).join('')}</select></label><p class="small">Фильтры применяются к доступным анкетам.</p>${next('Применить фильтры')}</form>${button('Сбросить','reset-filters','outline','close')}`;
 case 'match':return `<div class="centered">${heading('Это<br>взаимно!','Вы понравились друг другу. Самое время познакомиться.')}<div class="match-pair"><img src="/assets/mark.jpg" alt="Демо-портрет" ${!state.demo?'hidden':''}>${photo(p)?`<img src="${esc(photo(p))}" alt="${esc(p.name)}">`:avatar(p)}<span>♡</span></div></div><div class="push-bottom">${button('Написать первым','open-chat','primary','chat')}${button('Продолжить смотреть','feed','outline','')}</div>`;
 case 'matches':return `${heading('Симпатии','Вы нравитесь друг другу — напиши первым.')}<div class="tabs"><button data-tab="mutual" class="${state.tab==='mutual'?'active':''}">Взаимные ${state.matches.length}</button><button data-tab="outgoing" class="${state.tab==='outgoing'?'active':''}">Исходящие ${state.likes.length}</button></div>${state.tab==='outgoing'?state.likes.map(p=>personCard(p,true)).join('') || note('Здесь появятся анкеты, которые ты лайкнул в этой сессии.','heart'):`<div class="match-grid">${state.matches.map(m=>`<button class="match-tile" data-match="${esc(m.id)}">${state.demo?avatar(people.find(p=>p.userId===m.user.id)):`<span class="avatar fallback">${esc(m.user.name?.[0] || '?')}</span>`}<strong>${esc(m.user.name || 'Студент')}</strong><span>Написать ${icon('arrow')}</span></button>`).join('')}</div>${!state.matches.length?note('Пока нет взаимных симпатий. Загляни в ленту!','heart'):''}`}`;
 case 'empty':return emptyView();
 case 'chats':return `${heading('Чаты')}<label class="search">${icon('search')}<input id="chat-search" placeholder="Поиск по чатам" value="${esc(state.search)}" aria-label="Поиск по чатам"></label><div id="chat-list">${chatList()}</div>`;
 case 'chat':case 'meeting-card':return chatView();
 case 'meeting':return `${heading('Предложить встречу','Пусть знакомство выйдет за пределы чата.')}<form data-form="meeting">${input('place','Место встречи','','text','required minlength="3" maxlength="200" placeholder="Кофейня у главного корпуса"')}${input('meetAt','Дата и время','','datetime-local','required')}<p class="small">Встреча отправится собеседнику как сообщение. Встречайтесь в общественных местах.</p>${next('Предложить встречу')}</form>`;
 case 'report':return `${heading('Что случилось?','Расскажи, что не так с этим профилем. Мы рассмотрим жалобу и примем меры.')}<form data-form="report"><div class="radio-stack">${['Оскорбления','Спам','Чужие фото','Другое'].map((r,i)=>`<label class="choice"><input type="radio" name="reason" value="${r}" ${i===0?'checked':''}>${r}</label>`).join('')}</div><label class="field">Комментарий<textarea name="comment" maxlength="300" rows="4" placeholder="Что нам стоит знать?"></textarea></label>${next('Отправить жалобу')}</form>`;
 case 'report-sent':return `<div class="success-symbol">${icon('shield')}</div>${heading('Жалоба<br>отправлена','Команда модерации рассмотрит её и примет меры, если найдёт нарушение правил CAMPUS.')}${note('Твоя жалоба конфиденциальна. Ты можешь продолжить пользоваться приложением.','shield')}<div class="push-bottom">${button('Вернуться в CAMPUS','feed')}${!state.demo?button('Заблокировать пользователя','block-person','outline','shield'):''}</div>`;
 case 'events':return `${heading('События<br>в твоём<br>университете')}<div class="event-tools"><div class="chips">${['Все','Концерты','Встречи','Вечеринки'].map(c=>`<button class="chip ${state.category===c?'selected':''}" data-category="${c}">${c}</button>`).join('')}</div><button class="text-link" data-go="tickets">${icon('ticket')} Мои билеты</button></div>${state.events.filter(e=>state.category==='Все'||e.category===state.category || !e.category).map(e=>`<button class="event-card" data-event="${esc(e.id)}"><img src="${eventImage(e)}" alt="${state.demo?esc(e.title):'Иллюстрация события'}"><span class="event-date">${icon('calendar')}${date(e.startsAt)}</span><span class="event-card-bottom"><strong>${esc(e.title)}</strong><b>${money(e.price)}</b></span></button>`).join('') || note('Пока событий нет. Загляни чуть позже.','calendar')}${!state.demo?'<p class="small">Изображения событий — иллюстрации из макетов. API пока не хранит постеры.</p>':''}`;
 case 'event':case 'sold-out':return e?`<img class="event-cover" src="${eventImage(e)}" alt="${esc(e.title)}">${heading(esc(e.title))}<div class="event-facts"><p>${icon('calendar')}${date(e.startsAt)}</p><p>${icon('pin')}${esc(e.partner?.address || '')}</p><p>${icon('heart')}${esc(e.description || 'Знакомься с новыми людьми на событиях CAMPUS.')}</p></div>${route==='sold-out'||!e.freeSeats?`${note('<strong>Все места заняты</strong><br>Попробуй другое событие.','user')}${button('Другие события','events')}`:`<div class="price-card"><strong>${money(e.price)}</strong><span>Осталось <b>${e.freeSeats}</b> места</span></div>${button('Забронировать место','reserve','primary','ticket')}`}`:note('Событие не найдено','calendar');
 case 'reservation':return state.ticket?`${heading('Место ждёт тебя<br>30 минут','Мы зарезервировали один билет на событие.')} ${eventSummary(state.ticket.event || e)}<div class="receipt"><span>Билет</span><b>1 × ${money((state.ticket.event||e)?.price)}</b><strong>Итого</strong><strong>${money((state.ticket.event||e)?.price)}</strong></div><div class="timer-card">${icon('clock')} Оплатить до <strong data-countdown="${esc(state.ticket.reservedUntil)}">${remaining(state.ticket.reservedUntil)}</strong></div>${button('Перейти к оплате','checkout','primary','card')}${!state.demo?button('Отменить бронь','cancel-reservation','outline','close'):''}`:note('Сначала забронируй место на странице события.','ticket');
 case 'tickets':return `${heading('Мои билеты','Планы, которые хочется не пропустить.')}<div class="ticket-list">${state.tickets.map((t,i)=>`<button class="ticket-row" data-ticket="${i}">${eventSummary(t.event)}<span class="status ${t.status==='PAID'?'paid':''}">${ticketLabel(t)}</span></button>`).join('') || note('Пока нет билетов. Выбери событие в афише.','ticket')}</div>${button('Найти событие','events','outline','calendar')}`;
 case 'ticket':return state.ticket?`${heading(state.ticket.status==='PAID'?'Билет<br>подтверждён':'Твоя бронь')}${eventSummary(state.ticket.event || e)}<div class="ticket-stub">${icon('ticket')}<span class="status paid">${ticketLabel(state.ticket)}</span><p>Мероприятие: ${esc(state.ticket.eventId)}</p>${state.ticket.status==='PAID'?state.pass?.qrDataUrl?.startsWith('data:image/png;base64,')?`<img class="ticket-qr" src="${esc(state.pass.qrDataUrl)}" alt="QR-код для входа"><code>${esc(state.pass.token)}</code>${note(state.pass.checkedInAt?'Билет уже использован':'Покажи этот QR-код организатору на входе.','shield')}`:note('Демо-билет. Настоящий QR появляется после оплаты через API.','ticket'):button('Продолжить оплату','checkout')}</div>`:note('Выбери билет в разделе «Мои билеты».','ticket');
 case 'premium':return `${heading('CAMPUS<br>Premium','Больше знакомств и возможностей на кампусе.')}<img class="premium-cover" src="/assets/premium.jpg" alt="Студенты на кампусе">${note('<strong>∞ &nbsp; Лайки без лимита</strong>','heart')}<p class="intro">На 30 дней. После окончания вернётся обычный лимит лайков.</p>${button('Оформить Premium','buy-premium','primary','heart')}<p class="small centered">${state.demo?'Демо-цена: 349 ₽.':state.subscription?.active?'Активно до '+date(state.subscription.endsAt):money(state.subscription?.priceKopecks || 34900)+' на 30 дней'}</p>`;
 case 'checkout':return `${heading('Оплата заказа')}${state.payment?.kind==='PREMIUM'?note('CAMPUS Premium на 30 дней','heart'):eventSummary(state.ticket?.event || e)}<div class="receipt"><span>Состав заказа</span><b>${state.payment?.kind==='PREMIUM'?'Premium':'Билет на событие'}</b><strong>Итого</strong><strong>${money(state.payment?.amount ?? state.ticket?.event?.price ?? e?.price)}</strong></div>${note('Оплата пройдёт на стороне платёжного сервиса. Данные карты не передаются в CAMPUS.','shield')}${!state.demo&&safePaymentUrl(state.payment?.confirmationUrl)?`<a class="btn primary" href="${esc(safePaymentUrl(state.payment.confirmationUrl))}" target="${state.payment.confirmationUrl.includes('/sandbox')?'_self':'_blank'}" rel="noopener noreferrer" data-payment-open>Перейти к оплате ${icon('card')}</a>`:button(state.payment?.status==='FAILED'?'Повторить оплату':state.payment?'Перейти к оплате':'Создать платёж',state.payment?.status==='FAILED'?'retry-payment':'pay','primary','card')}${state.demo?'<p class="small centered">Демо: деньги не списываются.</p>':''}`;
 case 'payment-pending':return `<div class="success-symbol pulse">${icon('card')}</div>${heading('Проверяем<br>оплату','Подтверждение от платёжного сервиса может занять некоторое время.')}${state.demo?`<p class="small">Выбери результат тестовой оплаты:</p>${button('Успешно','demo-paid','primary','check')}${button('Ошибка оплаты','demo-failed','outline','close')}`:button('Проверить статус','check-payment','outline','clock')}${button('Посмотреть заказ','checkout','ghost','ticket')}`;
 case 'payment-success':if(!state.demo&&(state.payment?.status!=='SUCCEEDED'||state.payment?.requiresRefund))return note('Подтверждение оплаты ещё не получено. Открой заказ и проверь статус.','clock')+button('Посмотреть заказ','checkout');return `<div class="success-symbol">${icon('check')}</div>${heading(state.payment?.kind==='PREMIUM'?'Больше поводов<br>познакомиться!':'Готово, ты идёшь!','Оплата подтверждена.')} ${state.payment?.kind==='PREMIUM'?note('Premium активирован на 30 дней.','heart'):eventSummary(state.ticket?.event || e)}${button(state.payment?.kind==='PREMIUM'?'К знакомствам':'Открыть билет',state.payment?.kind==='PREMIUM'?'feed':'ticket')}`;
 case 'payment-review':return `${heading('Оплата получена,<br>билет не выдан','Бронь успела истечь или была отменена. Обратись к организатору для возврата оплаты.')}${note('Не оплачивай повторно этот заказ. Деньги требуют сверки с организатором.','shield')}${button('Мои билеты','tickets','outline','ticket')}`;
 case 'payment-failed':return `<div class="success-symbol">${icon('close')}</div>${heading('Оплата не прошла','Попробуй повторить платёж. Проверь баланс, лимит и данные карты.')}${state.ticket?note(`Бронь действует ещё <b data-countdown="${esc(state.ticket.reservedUntil)}">${remaining(state.ticket.reservedUntil)}</b>`,'clock'):''}${button('Повторить оплату','retry-payment')}${button('Посмотреть заказ','checkout','outline','ticket')}`;
 case 'expired':return `<div class="success-symbol">${icon('clock')}</div>${heading('Время брони<br>вышло','Место снова доступно другим участникам.')} ${eventSummary(state.ticket?.event || e)}${button('Проверить места','refresh-events','primary','search')}`;
 case 'reports':return `${tag('Модератор')}${heading('Жалобы<br>от пользователей')}${!state.demo?`<div class="tabs"><button data-report-status="OPEN" class="${state.reportStatus==='OPEN'?'active':''}">Новые</button><button data-report-status="CLOSED" class="${state.reportStatus==='CLOSED'?'active':''}">Закрытые</button></div>`:''}<div class="list">${state.reports.map(r=>`<button class="report-row" data-report="${esc(r.id)}">${icon('shield')}<span><strong>Жалоба #${esc(r.id.slice(-6))}</strong><small>${esc(r.reason)}</small><small>${date(r.createdAt)}</small></span>${icon('arrow')}</button>`).join('') || note('Все жалобы рассмотрены.','check')}</div>${state.demo||state.me?.role==='ADMIN'?button('Проверить билет','check-in','outline','ticket')+button('Управление событиями','manage-events','outline','calendar')+button('Отчёты команды','stats','ghost','download'):''}`;
 case 'report-detail':return state.report?`${tag('Модератор')}${heading('Рассмотрение<br>жалобы')}<p class="small">Жалоба #${esc(state.report.id)}</p>${note(`<strong>${esc(state.report.target?.profile?.name || 'Пользователь')}</strong><br>${esc(state.report.reason)}`,'user')}<p>Получена ${date(state.report.createdAt)}</p>${state.report.messages?.length?`<h3>Контекст переписки</h3><div class="messages">${state.report.messages.map(m=>`<div class="bubble">${esc(m.text)}</div>`).join('')}</div>`:''}${state.report.status==='OPEN'?button('Принять решение','decision')+button('Отклонить жалобу','reject-report','outline','close'):note('Решение: '+esc(state.report.decision),'shield')}`:note('Выбери жалобу из очереди.','shield');
 case 'decision':return `${heading('Принять решение<br>по жалобе')}<form data-form="decision"><div class="radio-stack">${[['WARNED','Предупреждение','Пользователь получит уведомление.'],['BLOCKED','Блокировка','Аккаунт будет заблокирован.'],['REJECTED','Отклонить жалобу','Нарушений не найдено.']].map(([v,t,c])=>`<label class="choice"><input type="radio" name="decision" value="${v}" ${v==='WARNED'?'checked':''}><span><strong>${t}</strong><small>${c}</small></span></label>`).join('')}</div>${note('Решение закроет все открытые жалобы на этого пользователя.','shield')}${next('Подтвердить решение')}</form>`;
 case 'manage-events':return `${tag('Организатор')}${heading('Управление<br>событиями')}${state.events.map(e=>`<button class="ticket-row" data-edit-event="${esc(e.id)}">${eventSummary(e)}<span class="status ${e.published!==false?'paid':''}">${e.published!==false?'Опубликовано':'Черновик'} · ${e.capacity-e.freeSeats} участников</span></button>`).join('')}${button('Создать событие','new-event','primary','plus')}${button('Отчёты команды','stats','outline','download')}`;
 case 'edit-event':{const ev=state.editEvent;return `${heading(ev?'Редактировать<br>событие':'Создать<br>событие')}<form data-form="event">${input('title','Название события',ev?.title || '','text','required minlength="3" maxlength="160"')}<label class="field">Партнёр<select name="partnerId" required><option value="">Выбери партнёра</option>${state.partners.map(p=>`<option value="${esc(p.id)}" ${ev?.partnerId===p.id||state.partner?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${button('Добавить нового партнёра','new-partner','outline','plus')}${input('startsAt','Дата и время',ev?new Date(new Date(ev.startsAt).getTime()-new Date(ev.startsAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'','datetime-local','required')}<div class="two-fields">${input('capacity','Вместимость',ev?.capacity || '60','number','required min="1" max="1000"')}${input('price','Цена, ₽',ev?ev.price/100:'450','number','required min="0" step="0.01"')}</div><label class="field">Категория<select name="category">${['Концерты','Встречи','Вечеринки'].map(c=>`<option ${ev?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Описание<textarea name="description" maxlength="2000">${esc(ev?.description || '')}</textarea></label>${input('posterUrl','Постер (URL)',ev?.posterUrl || '','text','maxlength="300" placeholder="https://…"')}<label class="check-row"><input type="checkbox" name="published" ${ev?.published!==false?'checked':''}><span>Опубликовать в афише</span></label>${next('Сохранить')}</form>`;}
 case 'new-partner':return `${heading('Новый партнёр')}<form data-form="partner">${input('name','Название','','text','required minlength="2" maxlength="120"')}${input('address','Адрес','','text','required minlength="3" maxlength="200"')}<label class="field">Условия<textarea name="terms" maxlength="500"></textarea></label>${next('Добавить партнёра')}</form>`;
 case 'stats':return `${tag('Администратор')}${heading('Отчёты команды')}<form data-form="stats"><div class="two-fields">${input('from','С',state.stats?.from?.slice(0,10) || new Date().toISOString().slice(0,7)+'-01','date','required')}${input('to','До (не включая)',state.stats?.to?.slice(0,10) || new Date(Date.now()+86400000).toISOString().slice(0,10),'date','required')}</div>${next('Показать')}</form>${state.stats?`<div class="stat-grid">${[['Регистрации',state.stats.newUsers],['Совпадения',state.stats.matches],['Выручка',money(state.stats.revenueKopecks)],['Встречи',state.stats.meetingsAccepted],['Билеты',state.stats.ticketsPaid],['Premium',state.stats.premiumBought]].map(([t,v])=>`<div><span>${t}</span><strong>${v}</strong></div>`).join('')}</div>${state.daily.length?`<h3>Регистрации по дням</h3><div class="daily-chart">${state.daily.map(row=>`<div><span>${esc(row.day)}</span><meter min="0" max="${Math.max(...state.daily.map(d=>d.registrations),1)}" value="${row.registrations}"></meter><strong>${row.registrations}</strong></div>`).join('')}</div>`:''}${button('Экспорт отчёта (CSV)','export','outline','download')}`:note('Выбери период для отчёта.','calendar')}`;
 case 'history':return `${heading('История платежей')}${state.history.map(p=>`<div class="note"><div><strong>${p.kind==='PREMIUM'?'Premium':'Билет'} · ${money(p.amount)}</strong><p>${date(p.createdAt)}</p><span>${p.status==='SUCCEEDED'?'Оплачено':p.status==='FAILED'?'Не оплачено':'Ожидает оплаты'}</span></div></div>`).join('') || note('Пока платежей нет','card')}`;
 case 'preferences':return `${heading('Твой CAMPUS')}<form data-form="preferences"><label class="switch-card"><span>Уведомления о совпадениях и сообщениях</span><input type="checkbox" name="notifications" role="switch" ${state.me?.profile?.notifications!==false?'checked':''}></label><label class="field">Тема<select name="theme"><option value="light">Светлая</option><option value="dark" ${state.me?.profile?.theme==='dark'?'selected':''}>Тёмная</option></select></label>${next('Сохранить')}</form>`;
 case 'blocks':return `${heading('Заблокированные')}${state.blocks.map(b=>`<div class="note"><span>${esc(b.blocked.profile?.name || 'Пользователь')}</span><button class="text-link" data-unblock="${esc(b.blockedId)}">Разблокировать</button></div>`).join('') || note('Список пуст','shield')}`;
 case 'check-in':return `${heading('Проверить билет','Вставь код, считанный сканером QR.')}<form data-form="check-in">${input('token','Код билета','','text','required')}${next('Отметить вход')}</form>`;
 case 'safety':return `${heading('Здесь должно<br>быть комфортно')}<div class="prose"><h3>Уважай чужие границы</h3><p>Знакомься без давления, оскорблений и навязчивости. Отказ — тоже ответ.</p><h3>Будь собой</h3><p>Используй свои фотографии и рассказывай о себе честно. Не публикуй чужие личные данные.</p><h3>Встречайся безопасно</h3><p>Выбирай общественные места, сообщи другу о планах. Не отправляй деньги незнакомым людям.</p><h3>Если что-то не так</h3><p>Отправь жалобу из анкеты или чата. Модератор рассмотрит ситуацию.</p></div>${button('Понятно','back','outline','check')}`;
 case 'privacy-policy':return `${heading('О персональных<br>данных')}<div class="prose"><p>CAMPUS использует университетскую почту, дату рождения, анкету, фотографии и переписку для работы сервиса знакомств.</p><p>Почта и дата рождения не показываются в ленте. Участники видят данные твоей анкеты. Настройка приватности позволяет скрыть анкету от своего института.</p><p>Удалить аккаунт можно в настройках приватности. Будут удалены данные, связанные с аккаунтом, согласно текущей реализации API.</p>${note('Это описание работы учебного проекта. Перед публичным запуском владельцу сервиса нужно указать оператора данных, контакты и утвердить полную политику.','book')}</div>${button('Назад','back','outline','back')}`;
 case 'account':return `${heading('Аккаунт')}${note(esc(state.me?.universityEmail),'mail')}${note(`Статус студента: ${state.me?.isVerified?'подтверждён':'не подтверждён'}`,'shield')}${button('Выйти','logout','outline','logout')}`;
 default:return `${heading('Экран не найден')}${button('На главную',state.me?'feed':'welcome')}`;
 }
}
function listButton(title,copy,to,ico){return `<button class="list-button" data-go="${to}">${icon(ico)}<span><strong>${title}</strong><small>${copy}</small></span>${icon('arrow')}</button>`;}
function personCard(p,compact=false){return `<button class="person-card ${compact?'compact':''}" data-person="${esc(p.userId)}">${photo(p)?`<img src="${esc(photo(p))}" alt="${esc(p.name)}">`:'<span class="photo-fallback">'+icon('user')+'</span>'}<div class="person-overlay"><h2>${esc(p.name)}${p.age?', '+p.age:''} <span class="verified-badge">✓</span></h2><p>${esc(p.institute)}</p>${!compact?`<div class="person-quote">“ <span>${esc(p.quote || p.about || 'Давай познакомимся?')}</span></div>`:''}</div></button>`;}
function emptyView(){return `<div class="empty-state"><div class="empty-art">${icon('calendar')}<span>♡</span></div>${heading('Пока все,<br>но ненадолго','Мы показали все доступные анкеты. Новые студенты уже на подходе!')}${button('Изменить фильтры','filters','primary','filter')}${button('Обновить','refresh-feed','outline','clock')}</div>`;}
function eventSummary(e){return e?`<div class="event-summary"><img src="${eventImage(e)}" alt="${esc(e.title)}"><div><h3>${esc(e.title)}</h3><p>${icon('calendar')}${date(e.startsAt)}</p>${e.partner?.address?`<p>${icon('pin')}${esc(e.partner.address)}</p>`:''}</div></div>`:'';}
function ticketLabel(t){return t.status==='PAID'?'✓ Оплачен':t.status==='RELEASED'||new Date(t.reservedUntil)<=new Date()?'Бронь истекла':'Место забронировано';}
function chatList(){return state.matches.filter(m=>m.user.name?.toLowerCase().includes(state.search.toLowerCase())).map(m=>`<button class="chat-row" data-match="${esc(m.id)}">${state.demo?avatar(people.find(p=>p.userId===m.user.id)):`<span class="avatar fallback">${esc(m.user.name?.[0] || '?')}</span>`}<span><strong>${esc(m.user.name || 'Студент')} <span class="verified-badge">✓</span></strong><small>${esc(m.lastMessage?.text || 'Начни с «привет»')}</small></span>${icon('arrow')}</button>`).join('') || note('Здесь начнутся ваши разговоры после взаимной симпатии.','chat');}
function chatView(){if(!state.match)return note('Выбери собеседника в чатах.','chat');return `<div class="chat-heading"><h2>${esc(state.match.user.name)} <span class="verified-badge">✓</span></h2><button class="icon-btn" data-action="report-chat" aria-label="Пожаловаться на собеседника">${icon('shield')}</button></div><div class="messages" id="messages">${state.messages.filter(m=>state.demo||!decodeMeeting(m.text)).map(m=>`<div class="bubble ${m.senderId===state.me?.id?'own':''}"><div>${messageBody(m)}</div><time>${new Date(m.sentAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}${!state.demo?state.meetings.map(m=>meetingCard(m)).join(''):''}${state.demo&&state.meeting&&!state.messages.some(m=>decodeMeeting(m.text)?.id===state.meeting.id)?meetingCard():''}</div>${button('Предложить встречу','meeting','outline','calendar')}<form class="composer" data-form="message"><input name="text" required maxlength="2000" placeholder="Сообщение…" aria-label="Сообщение" autocomplete="off"><button class="send-button" type="submit" aria-label="Отправить сообщение">${icon('send')}</button></form>${state.hasOlder?button('Загрузить предыдущие сообщения','older-messages','ghost','clock'):''}`;}
function messageBody(message){const decoded=decodeMeeting(message.text);if(!decoded)return esc(message.text);if(decoded.type==='meeting-status')return decoded.status==='ACCEPTED'?'✓ Встреча подтверждена!':'Встреча отклонена';const replies=state.messages.filter(m=>m.senderId!==message.senderId).map(m=>decodeMeeting(m.text)).filter(m=>m?.type==='meeting-status'&&m.id===decoded.id);return meetingCard({...decoded,proposerId:message.senderId,status:replies.at(-1)?.status || 'PROPOSED'});}
function meetingCard(m=state.meeting){return `<div class="meeting-card" data-meeting-id="${esc(m.id)}"><h3>${icon('calendar')} Предложение о встрече</h3><p>${esc(m.place)}</p><p>${date(m.meetAt)}</p>${m.status==='PROPOSED'?m.proposerId===state.me?.id?'<span class="status">Ждём ответа собеседника</span>':`${button('Согласиться','accept-meeting','primary','check')}${button('Другой вариант','decline-meeting','outline','close')}`:`<span class="status ${m.status==='ACCEPTED'?'paid':''}">${m.status==='ACCEPTED'?'Встреча подтверждена!':'Встреча отклонена'}</span>`}</div>`;}
async function load(){clearInterval(pollTimer);const id=++sequence;route=location.hash.slice(1)||'welcome';state.error='';state.search='';const publicRoutes=['welcome','birth','university','email','code','privacy-policy','safety'];if(!state.demo&&!api.token&&!publicRoutes.includes(route)){go('welcome');return;}
 const teamRoutes=['reports','report-detail','decision','manage-events','edit-event','new-partner','stats','check-in'];try {state.loading=true;render();if(!state.me&&(api.token||state.demo))state.me=await api.request('/profile');if(teamRoutes.includes(route)&&!state.demo){const admin=['manage-events','edit-event','new-partner','stats','check-in'].includes(route);if(!['ADMIN',...(admin?[]:['MODERATOR'])].includes(state.me?.role))throw new Error('Этот раздел доступен только команде CAMPUS.');}
 if(['feed','empty'].includes(route)){const list=await api.request('/feed?'+new URLSearchParams({limit:'50',...Object.fromEntries(Object.entries(state.filter).filter(([,v])=>v!==''&&v!=null))}));state.feed=list.filter(p=>(!state.filter.goal||p.goal===state.filter.goal)&&(!state.filter.university||p.university.toLowerCase().includes(state.filter.university.toLowerCase())));}
 if(['matches','chats'].includes(route))state.matches=await api.request('/matches');
 if(route==='matches'&&!state.demo)state.likes=await api.request('/likes/outgoing');
 if(['profile','premium'].includes(route)&&!state.demo)state.subscription=await api.request('/subscription');
 if(route==='blocks'&&!state.demo)state.blocks=await api.request('/blocks');
 if(route==='edit-event')state.partners=await api.request('/admin/partners');
 if(route==='manage-events'&&!state.demo)state.events=await api.request('/admin/events');
 if(['event','sold-out'].includes(route)&&state.event&&!state.demo)state.event=await api.request('/events/'+state.event.id);
 if(route==='ticket'&&state.ticket?.status==='PAID'&&!state.demo)state.pass=await api.request('/tickets/'+state.ticket.eventId+'/pass');
 if(route==='report-detail'&&state.report&&!state.demo)state.report=await api.request('/admin/reports/'+state.report.id);
 if(['events','manage-events'].includes(route)||!state.events.length && ['event','sold-out','reservation','checkout','expired'].includes(route))state.events=await api.request('/events');
 if(!state.demo&&!state.payment&&['reservation','checkout','payment-pending','payment-success','payment-failed','expired'].includes(route)){
 let saved;try{saved=JSON.parse(storage.get('campus-checkout') || 'null');}catch{}
 if(saved?.userId===state.me?.id){state.paymentKey=saved.key;if(saved.kind==='TICKET'){state.tickets=await api.request('/tickets');state.ticket=state.tickets.find(t=>t.eventId===saved.eventId);if(state.ticket)state.event=state.ticket.event;}
 if(saved.created)state.payment=saved.paymentId?await api.request('/payments/'+saved.paymentId):await api.request('/payments',{method:'POST',key:saved.key,body:{kind:saved.kind,...(saved.kind==='TICKET'?{eventId:saved.eventId}:{})}});}
 }
 if(route==='tickets')state.tickets=await api.request('/tickets');
 if(route==='stats'&&!state.stats){const from=new Date().toISOString().slice(0,7)+'-01',to=new Date(Date.now()+86400000).toISOString().slice(0,10);state.stats=await api.request(`/admin/stats?from=${from}&to=${to}`);}
 if(['chat','meeting','meeting-card'].includes(route)&&!state.match&&!state.demo){state.matches=await api.request('/matches');state.match=state.matches.find(m=>m.id===storage.get('campus-match')) || null;}
 if(route==='ticket'&&!state.ticket&&!state.demo){state.tickets=await api.request('/tickets');state.ticket=state.tickets.find(t=>t.eventId===storage.get('campus-ticket'));if(state.ticket){state.event=state.ticket.event;if(state.ticket.status==='PAID')state.pass=await api.request('/tickets/'+state.ticket.eventId+'/pass');}}
 if(['chat','meeting-card'].includes(route)){if(!state.match&&state.demo)state.match=api.matches[0];if(state.match){state.messages=await api.request(`/matches/${state.match.id}/messages`);if(!state.demo)state.meetings=await api.request(`/matches/${state.match.id}/meetings`);state.hasOlder=state.messages.length===50;}if(route==='meeting-card'&&state.demo&&!state.meeting)state.meeting={id:'demo-incoming',proposerId:'demo-anya',place:'Кофейня у главного корпуса',meetAt:new Date(Date.now()+86400000).toISOString(),status:'PROPOSED'};}
 if(route==='reports')state.reports=await api.request('/admin/reports'+(!state.demo?'?status='+state.reportStatus:''));
 if(route==='history'&&!state.demo)state.history=await api.request('/payments');
 if(route==='stats'&&state.stats&&!state.demo)state.daily=await api.request(`/admin/stats/daily?from=${state.stats.from}&to=${state.stats.to}`);
 if(state.demo){if(!state.event)state.event=api.events[0];if(['report-detail','decision'].includes(route)&&!state.report)state.report=api.reports[0];if(['reservation','ticket','checkout','payment-pending','payment-success','payment-failed','expired'].includes(route)&&!state.ticket)state.ticket={eventId:state.event.id,event:state.event,status:route==='ticket'?'PAID':'RESERVED',reservedUntil:new Date(Date.now()+1800000).toISOString()};}
 }catch(error){if(id===sequence)state.error=error.message;}finally{if(id===sequence){state.loading=false;render();window.scrollTo(0,0);if(['chat','meeting-card'].includes(route)&&state.match)pollTimer=setInterval(pollMessages,5000);if(route==='payment-pending'&&!state.demo)pollTimer=setInterval(checkPayment,7000);}}}
async function pollMessages(){if(document.hidden)return;try{const messages=await api.request(`/matches/${state.match.id}/messages`);const meetings=state.demo?[]:await api.request(`/matches/${state.match.id}/meetings`);const changed=JSON.stringify(meetings)!==JSON.stringify(state.meetings);state.meetings=meetings;if(changed||JSON.stringify(messages)!==JSON.stringify(state.messages)){state.messages=messages;const box=$('#messages');if(box){const form=$('.composer');const text=form?.elements.text.value;render();if(text&&$('.composer'))$('.composer').elements.text.value=text;$('#messages')?.scrollTo(0,100000);}}}catch{/* Manual navigation will display connection errors. */}}
async function checkPayment(){if(!state.payment)return;try{const p=state.demo?await api.request('/payments',{method:'POST',body:{kind:state.payment.kind,...(state.payment.kind==='TICKET'?{eventId:state.ticket.eventId}:{})},key:state.payment.idempotencyKey}):await api.request('/payments/'+state.payment.id);state.payment=p;if(p.requiresRefund){go('payment-review');return;}if(p.status==='SUCCEEDED'){if(p.kind==='TICKET'){state.tickets=await api.request('/tickets');state.ticket=state.tickets.find(t=>t.eventId===state.ticket.eventId)||state.ticket;}go('payment-success');}else if(p.status==='FAILED')go('payment-failed');else if(!state.demo)toast('Подтверждение пока не получено. Проверим ещё раз.');}catch(error){toast(error.message);}}
function updateTimers(){document.querySelectorAll('[data-countdown]').forEach(el=>{el.textContent=remaining(el.dataset.countdown);if(el.textContent==='00:00'&&['reservation','payment-failed'].includes(route))go('expired');});const resend=$('.resend');if(resend){const seconds=Math.max(0,Math.ceil((Number(storage.get('campus-resend'))-Date.now())/1000));resend.disabled=seconds>0;const label=$('[data-resend]');if(label)label.textContent=seconds?`через ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:'';}}
setInterval(updateTimers,1000);
async function rate(like,person=state.feed[0]){if(!person)return;state.selected=person;const result=await api.request('/likes',{method:'POST',body:{toUserId:person.userId,isLike:like}});if(like)state.likes.push(person);state.feed=state.feed.filter(p=>p.userId!==person.userId);if(result.match){state.matches=await api.request('/matches');state.match=state.matches.find(m=>m.id===result.matchId);go('match');}else{toast(like?'Симпатия отправлена':'Анкета пропущена');if(route!=='feed')go('feed');else render();}}
async function act(action){
 if(action==='start-demo'){Object.assign(state,{me:null,draft:null,feed:[],matches:[],messages:[],meetings:[],events:[],tickets:[],ticket:null,event:null,selected:null,match:null,payment:null,paymentKey:null,meeting:null,likes:[],reports:[],report:null,stats:null,daily:[],history:[],subscription:null,pass:null,partners:[],editEvent:null,blocks:[],filter:{goal:'',university:''}});state.demo=true;api.demo=true;api.resetDemo();state.me=null;storage.set('campus-demo','true');state.draft=null;go('feed');return;}
 if(['exit-demo','logout'].includes(action)){storage.remove('campus-token');storage.remove('campus-demo');storage.remove('campus-checkout');storage.remove('campus-match');storage.remove('campus-ticket');api.token='';api.demo=false;Object.assign(state,{demo:false,me:null,draft:null,feed:[],matches:[],messages:[],events:[],tickets:[],ticket:null,event:null,selected:null,match:null,payment:null,paymentKey:null,meeting:null,likes:[],reports:[],report:null,meetings:[],subscription:null,pass:null,history:[],stats:null,daily:[],partners:[],editEvent:null,blocks:[],birth:'',consent:false,stepEmail:'',filter:{goal:'',university:''}});go('welcome');return;}
 if(action==='back'){if(route==='privacy-policy'){go('birth');return;}go(['person','filters','empty','match'].includes(route)?'feed':['chat','meeting','meeting-card'].includes(route)?'chats':['event','reservation','ticket','sold-out','checkout','expired'].includes(route)?'events':state.me?'profile':'welcome');return;}
 if(action==='onboarding'){go('birth');return;}
 if(action==='create-profile'||action==='edit-profile'){state.draft=null;go('edit-profile');return;}
 if(action==='open-photos'){go('photos');return;}
 if(action==='save-profile'){if(draft().interests.length<3||draft().interests.length>10)throw new Error('Выбери от 3 до 10 интересов.');const {photos,userId,...body}=draft();state.me=await api.request('/profile',{method:'PUT',body});state.draft=null;go(state.me.profile.photos.length?'profile':'photos');return;}
 if(action==='finish-photos'){if(!state.me?.profile?.photos?.length)throw new Error('Добавь хотя бы одно фото, чтобы анкета участвовала в знакомствах.');go('profile');return;}
 if(action==='like'||action==='pass'){await rate(action==='like');return;}
 if(action==='like-person'){await rate(true,selectedPerson());return;}
 if(action==='next-photo'||action==='prev-photo'){const n=selectedPerson()?.photos.length||1;state.photo=(state.photo+(action==='next-photo'?1:n-1))%n;render();return;}
 if(action==='reset-filters'){state.filter={goal:'',university:''};go('feed');return;}
 if(action==='refresh-feed'){go('feed');return;}
 if(action==='open-chat'){if(!state.match)throw new Error('Сначала нужна взаимная симпатия.');go('chat');return;}
 if(action==='report-chat'){state.selected={userId:state.match.user.id,name:state.match.user.name};go('report');return;}
 if(action==='reserve'){if(!selectedEvent())return;state.ticket=await api.request(`/events/${selectedEvent().id}/tickets`,{method:'POST'});state.ticket.event ||= selectedEvent();state.payment=null;state.paymentKey=crypto.randomUUID();rememberCheckout();go('reservation');return;}
 if(action==='buy-premium'){state.paymentKey = state.payment?.kind==='PREMIUM'&&state.payment.status==='PENDING'?state.payment.idempotencyKey:crypto.randomUUID();state.payment=await api.request('/payments',{method:'POST',body:{kind:'PREMIUM'},key:state.paymentKey});rememberCheckout();go('checkout');return;}
 if(action==='pay'){if(state.ticket&&state.payment?.kind!=='PREMIUM'&&new Date(state.ticket.reservedUntil)<=new Date()){go('expired');return;}state.paymentKey ||= crypto.randomUUID();if(!state.payment)state.payment=await api.request('/payments',{method:'POST',body:{kind:'TICKET',eventId:state.ticket.eventId},key:state.paymentKey});rememberCheckout();if(state.demo){go('payment-pending');return;}if(state.payment.status==='SUCCEEDED'){await checkPayment();return;}const url=safePaymentUrl(state.payment.confirmationUrl);if(!url)throw new Error('Платёжный сервис не вернул ссылку на оплату. Попробуй ещё раз.');render();toast('Платёж создан. Нажми «Перейти к оплате», чтобы открыть платёжный сервис.');return;}
 if(action==='demo-paid'||action==='demo-failed'){if(!state.demo)return;api.finishDemoPayment(action==='demo-paid'?'SUCCEEDED':'FAILED');if(action==='demo-paid'&&state.ticket)state.ticket.status='PAID';go(action==='demo-paid'?'payment-success':'payment-failed');return;}
 if(action==='check-payment'){await checkPayment();return;}
 if(action==='retry-payment'){const kind=state.payment?.kind || 'TICKET';state.paymentKey=crypto.randomUUID();state.payment=await api.request('/payments',{method:'POST',key:state.paymentKey,body:{kind,...(kind==='TICKET'?{eventId:state.ticket.eventId}:{})}});rememberCheckout();go('checkout');return;}
 if(action==='refresh-events'){state.event=null;go('events');return;}
 if(action==='new-event'){state.editEvent=null;go('edit-event');return;}
 if(action==='team'){go('reports');return;}
 if(action==='reject-report'){await decide('REJECTED');return;}
 if(action==='resend'){if(Date.now()<Number(storage.get('campus-resend')))return;await api.request('/auth/email/request',{method:'POST',body:{email:state.stepEmail}});storage.set('campus-resend',String(Date.now()+60000));toast('Код отправлен');render();return;}
 if(action==='accept-meeting'||action==='decline-meeting'){const status=action==='accept-meeting'?'ACCEPTED':'DECLINED';if(state.demo&&state.meeting.id==='demo-incoming')state.meeting.status=status;else {state.meeting=await api.request(`/meetings/${state.meeting.id}`,{method:'PATCH',body:{status}});if(state.demo)await api.request(`/matches/${state.match.id}/messages`,{method:'POST',body:{clientId:`meeting-${state.meeting.id}-${status}`,text:'CAMPUS::'+JSON.stringify({type:'meeting-status',id:state.meeting.id,status})}});else state.meetings=await api.request(`/matches/${state.match.id}/meetings`);state.messages=await api.request(`/matches/${state.match.id}/messages`);}render();return;}
 if(action==='older-messages'){const older=await api.request(`/matches/${state.match.id}/messages?before=${encodeURIComponent(state.messages[0].sentAt)}`);const ids=new Set(state.messages.map(m=>m.id));state.messages=[...older.filter(m=>!ids.has(m.id)),...state.messages];state.hasOlder=older.length===50;render();return;}
 if(action==='cancel-reservation'){await api.request(`/events/${state.ticket.eventId}/tickets`,{method:'DELETE'});state.ticket=null;state.payment=null;storage.remove('campus-checkout');go('tickets');return;}
 if(action==='block-person'){if(!selectedPerson())return;await api.request(`/users/${selectedPerson().userId}/block`,{method:'POST'});state.match=null;state.meetings=[];go('feed');toast('Пользователь заблокирован');return;}
 if(action==='export'){const s=state.stats;const csv='\uFEFF'+Object.entries(s).map(([k,v])=>`${k};${String(v).replaceAll(';',',')}`).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='campus-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(titles[action]||['delete-confirm','new-partner','account','safety','preferences','blocks','check-in','history'].includes(action)){go(action);return;}
}
async function decide(decision){if(!state.report)throw new Error('Выбери жалобу.');await api.request(`/admin/reports/${state.report.id}/decision`,{method:'POST',body:{decision}});toast('Решение зафиксировано');state.report=null;go('reports');}
document.addEventListener('click',async event=>{if(event.target.closest('[data-payment-open]')){go('payment-pending');return;}const target=event.target.closest('button,[data-go]');if(!target || target.disabled)return;try{if(target.dataset.go){go(target.dataset.go);return;}if(target.dataset.person){choosePerson(target.dataset.person);go('person');return;}if(target.dataset.match){state.match=state.matches.find(m=>m.id===target.dataset.match);state.meeting=null;go('chat');return;}if(target.dataset.event){state.event=state.events.find(e=>e.id===target.dataset.event);go(state.event.freeSeats?'event':'sold-out');return;}if(target.dataset.ticket!==undefined){state.ticket=state.tickets[Number(target.dataset.ticket)];state.event=state.ticket.event;state.payment=null;state.paymentKey=crypto.randomUUID();rememberCheckout();go(state.ticket.status==='PAID'?'ticket':new Date(state.ticket.reservedUntil)>new Date()?'reservation':'expired');return;}if(target.dataset.reportStatus){state.reportStatus=target.dataset.reportStatus;load();return;}if(target.dataset.editEvent){state.editEvent=state.events.find(e=>e.id===target.dataset.editEvent);go('edit-event');return;}if(target.dataset.report){state.report=state.reports.find(r=>r.id===target.dataset.report);go('report-detail');return;}if(target.dataset.interest){const d=draft(),i=target.dataset.interest;if(d.interests.includes(i))d.interests=d.interests.filter(x=>x!==i);else if(d.interests.length<10)d.interests.push(i);else throw new Error('Можно выбрать до 10 интересов.');render();return;}if(target.dataset.category){state.category=target.dataset.category;render();return;}if(target.dataset.tab){state.tab=target.dataset.tab;render();return;}if(target.dataset.unblock){await api.request(`/users/${target.dataset.unblock}/block`,{method:'DELETE'});go('blocks');return;}if(target.dataset.coverPhoto){const ids=state.me.profile.photos.map(p=>p.id);ids.splice(ids.indexOf(target.dataset.coverPhoto),1);ids.unshift(target.dataset.coverPhoto);await api.request('/profile/photos/order',{method:'PATCH',body:{ids}});state.me=await api.request('/profile');render();return;}if(target.dataset.removePhoto){await api.request(`/profile/photos/${target.dataset.removePhoto}`,{method:'DELETE'});state.me=await api.request('/profile');render();return;}if(target.dataset.action){if(['accept-meeting','decline-meeting'].includes(target.dataset.action)){const meetingId=target.closest('[data-meeting-id]')?.dataset.meetingId;const message=state.messages.find(m=>decodeMeeting(m.text)?.id===meetingId);if(!state.demo)state.meeting=state.meetings.find(m=>m.id===meetingId);else if(message)state.meeting={...decodeMeeting(message.text),proposerId:message.senderId,status:'PROPOSED'};}target.disabled=true;await act(target.dataset.action);}}catch(error){if(error.code==='LIKE_LIMIT'){go('premium');toast('Лимит лайков на сегодня исчерпан');}else toast(error.message);}finally{if(target.isConnected)target.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='chat-search'){state.search=event.target.value;$('#chat-list').innerHTML=chatList();}});
document.addEventListener('change',event=>{if(event.target.id==='screen-select'&&event.target.value)go(event.target.value);});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;submit.disabled=true;const data=Object.fromEntries(new FormData(form));try{switch(form.dataset.form){
 case 'birth':if(age(data.birthDate)<18)throw new Error('CAMPUS доступен только с 18 лет.');state.birth=data.birthDate;state.consent=!!data.consent;go('university');break;
 case 'university':state.university=data.university;state.institute=data.institute;go('email');break;
 case 'email':state.stepEmail=data.email.trim().toLowerCase();await api.request('/auth/email/request',{method:'POST',body:{email:state.stepEmail}});storage.set('campus-resend',String(Date.now()+60000));go('code');break;
 case 'code':{const result=await api.request('/auth/email/verify',{method:'POST',body:{email:state.stepEmail,code:data.code,...(state.birth?{birthDate:state.birth,acceptTerms:state.consent}:{})}});api.token=result.accessToken;storage.set('campus-token',result.accessToken);state.me=await api.request('/profile');go(result.isNew?'verified':state.me.profile?'feed':'edit-profile');break;}
 case 'profile':state.draft={...draft(),...data};go('interests');break;
 case 'photo':if(state.demo)await api.request('/profile/photos',{method:'POST',body:{storageKey:data.storageKey.trim()}});else {const file=form.elements.file.files[0];if(!file||file.size>5*1024*1024)throw new Error('Фото должно быть не больше 5 МБ');const body=new FormData();body.append('file',file);await api.request('/profile/photos/upload',{method:'POST',body});}state.me=await api.request('/profile');render();break;
 case 'privacy':{if(!state.me?.profile)throw new Error('Сначала заполни анкету.');const {photos,userId,...body}=state.me.profile;state.me=await api.request('/profile',{method:'PUT',body:{...body,hideFromInstitute:!!data.hide,isVisible:!!data.visible}});toast('Приватность сохранена');break;}
 case 'delete':await api.request('/profile',{method:'DELETE'});await act('logout');toast('Аккаунт удалён');break;
 case 'filters':state.filter={goal:data.goal,university:data.university || '',...(!state.demo?{minAge:data.minAge,maxAge:data.maxAge}:{})};go('feed');break;
 case 'message':{if(!data.text.trim())return;const m=await api.request(`/matches/${state.match.id}/messages`,{method:'POST',body:{text:data.text.trim(),clientId:form.dataset.clientId ||= crypto.randomUUID()}});delete form.dataset.clientId;state.messages.push(m);render();$('#messages')?.scrollTo(0,100000);$('.composer input')?.focus();break;}
 case 'meeting':{if(new Date(data.meetAt)<=new Date())throw new Error('Выбери время в будущем.');if(!state.demo){state.meeting=await api.request(`/matches/${state.match.id}/meetings`,{method:'POST',body:{place:data.place,meetAt:new Date(data.meetAt).toISOString()}});go('meeting-card');break;}if(!form.dataset.pendingMeeting)form.dataset.pendingMeeting=JSON.stringify(await api.request(`/matches/${state.match.id}/meetings`,{method:'POST',body:{place:data.place,meetAt:new Date(data.meetAt).toISOString()}}));state.meeting=JSON.parse(form.dataset.pendingMeeting);await api.request(`/matches/${state.match.id}/messages`,{method:'POST',body:{clientId:`meeting-${state.meeting.id}`,text:encodeMeeting(state.meeting)}});delete form.dataset.pendingMeeting;go('meeting-card');break;}
 case 'report':{const targetId=selectedPerson()?.userId;if(!targetId)throw new Error('Сначала выбери анкету.');await api.request('/reports',{method:'POST',body:{targetId,reason:`${data.reason}${data.comment?': '+data.comment:''}`}});go('report-sent');break;}
 case 'decision':await decide(data.decision);break;
 case 'preferences':{if(!state.me?.profile)throw new Error('Сначала заполни анкету');const {photos,userId,...body}=state.me.profile;state.me=await api.request('/profile',{method:'PUT',body:{...body,theme:data.theme,notifications:!!data.notifications}});toast('Настройки сохранены');render();break;}
 case 'check-in':await api.request('/admin/tickets/check-in',{method:'POST',body:{token:data.token.trim()}});toast('Билет действителен. Вход отмечен.');form.reset();break;
 case 'partner':state.partner=await api.request('/admin/partners',{method:'POST',body:data});go('edit-event');toast('Партнёр добавлен');break;
 case 'event':if(new Date(data.startsAt)<=new Date())throw new Error('Выбери дату в будущем.');await api.request('/admin/events'+(state.editEvent?'/'+state.editEvent.id:''),{method:state.editEvent?'PATCH':'POST',body:{title:data.title,partnerId:data.partnerId,startsAt:new Date(data.startsAt).toISOString(),capacity:Number(data.capacity),price:Math.round(Number(data.price)*100),category:data.category,description:data.description,posterUrl:data.posterUrl,published:!!data.published}});state.editEvent=null;go('manage-events');toast('Событие опубликовано');break;
 case 'stats':if(data.to<=data.from)throw new Error('Конец периода должен быть позже начала.');state.stats=await api.request(`/admin/stats?from=${data.from}&to=${data.to}`);if(!state.demo)state.daily=await api.request(`/admin/stats/daily?from=${data.from}&to=${data.to}`);render();break;
 }}catch(error){toast(error.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
window.addEventListener('hashchange',load);load();
